using System;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;
public static class ProbeEditorTick{public static object Main(){var t=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("Unity.Pipeline.Editor.Commands.AutoTickCommand",false)).First(x=>x!=null);const BindingFlags f=BindingFlags.Static|BindingFlags.NonPublic;return new{enabled=(bool)t.GetField("s_Enabled",f).GetValue(null),intervalMs=(long)t.GetField("s_IntervalMs",f).GetValue(null),Application.runInBackground,EditorApplication.isPaused,EditorApplication.isPlaying,persistedEnabled=SessionState.GetBool("Unity.Pipeline.AutoTick.Enabled",false),persistedInterval=SessionState.GetInt("Unity.Pipeline.AutoTick.IntervalMs",-1)};}}
